from boltons.strutils import parse_int_list as new

def old(range_string, delim=',', range_delim='-'):
    output = []
    for x in range_string.strip().split(delim):
        if range_delim in x:
            range_limits = list(map(int, x.split(range_delim)))
            output += list(range(min(range_limits), max(range_limits)+1))
        elif not x:
            continue
        else:
            output.append(int(x))
    return sorted(output)

cases = ['1,3,5-8,10-11,15', ' 1, 3 ,5-8,10-11,15 ', '5-8', '8-5', '1,1,2',
         '1,,2', '', '   ', ',', '1,', '5 - 8', '1-2,2-3', '15-10,3,3',
         '10-11,1-2', '1-2-3', '1-', '-', 'a']
mismatch = 0
for c in cases:
    try:
        o = ('ok', old(c))
    except Exception as e:
        o = ('err', type(e).__name__)
    try:
        n = ('ok', new(c))
    except Exception as e:
        n = ('err', type(e).__name__)
    flag = '' if o[0] == n[0] else '   <-- CHANGED'
    if flag:
        mismatch += 1
    print('%-24r old=%-18s new=%-18s%s' % (c, o, n, flag))
print('legacy-behavior mismatches:', mismatch)
PY
